TYPE.TEST:


SetFunctionName("DegToRad");
Validate( IsEqualWithEpsilon(DegToRad(180.0f), PI) );
Validate( IsEqualWithEpsilon(DegToRad(360.0f), TWO_PI) );
Validate( IsEqualWithEpsilon(DegToRad(0.0f), 0.0f) );



        SetFunctionName("RadToDeg");
        Validate(IsEqualWithEpsilon(RadToDeg(0.0f), 0.f, SMALL_FLOAT));

#if defined EA_PLATFORM_PS3_SPU        

        Validate(IsEqualWithinPercent(RadToDeg(PI), 180.f, 0.0001));
        Validate(IsEqualWithinPercent(RadToDeg(TWO_PI), 360.f, 0.0001));
#else
        Validate(IsEqualWithEpsilon(RadToDeg(PI), 180.f, SMALL_FLOAT));
        Validate(IsEqualWithEpsilon(RadToDeg(TWO_PI), 360.f, SMALL_FLOAT));
#endif



for (int i = 0; i < NUM_SINCOS_VALUES; ++i)
{
    SetFunctionName("Sin test[%d]", i);
    Validate(IsEqualWithEpsilon(Sin(sincos_values[i].input),
        sincos_values[i].output1, FSIN_EPSILON));
}



for (int i = 0; i < NUM_SINCOS_VALUES; ++i)
