}



for (int i = 0; i < NUM_ATAN2_VALUES; ++i)
{
    float_test_type atan2Result = ATan2(atan2_values[i].x, atan2_values[i].y);
    bool result = IsEqualWithEpsilon(atan2Result, (float_test_type)atan2_values[i].output, (float_test_type)FATAN_EPSILON);
    // Special case:  PI and -PI should be considered equally valid.
    if( atan2_values[i].output == -3.141593f && !result )
    {
        result = IsEqualWithEpsilon(atan2Result, (float_test_type)3.141593f, (float_test_type)FATAN_EPSILON);
    }
    #if 1
    SetFunctionName("ATan2 test[%d] ", i);
    #else
    SetFunctionName("ATan2 test[%d] result: %f expected %f", i, (float)atan2Result, atan2_values[i].output);
    #endif
    Validate(result);
}



        SetFunctionName("NormalizeAngle");
        Validate(IsEqualWithEpsilon(NormalizeAngle(TWO_PI + 1.1f), 1.1f));
	    Validate(IsEqualWithEpsilon(NormalizeAngle( QUARTER_PI),  QUARTER_PI));
	    Validate(IsEqualWithEpsilon(NormalizeAngle(-QUARTER_PI), -QUARTER_PI));
	    Validate(IsEqualWithEpsilon(NormalizeAngle(PI + 0.1f), -PI + 0.1f));
	    Validate(IsEqualWithEpsilon(NormalizeAngle(-PI + 0.1f), -PI + 0.1f));
	    Validate(IsEqualWithEpsilon(NormalizeAngle(0.f), 0.f));
	    Validate(IsEqualWithEpsilon(NormalizeAngle(TWO_PI), 0.f));
	    Validate(IsEqualWithEpsilon(NormalizeAngle(-PI - 0.1f), PI - 0.1f));



float_test_type fSin, fCos;

for (int i = 0; i < NUM_SINCOS_VALUES; ++i)
{
    SetFunctionName("SinCos(a, sin_out, cos_out) test[%d]", i);
    SinCos((float_test_type)(sincos_values[i].input), fSin, fCos);

    Validate(IsEqualWithEpsilon((float_basic_type) fSin, (float_basic_type) sincos_values[i].output1, (float_basic_type) FSINCOS_EPSILON));
    Validate(IsEqualWithEpsilon((float_basic_type) fCos, (float_basic_type) sincos_values[i].output2, (float_basic_type) FSINCOS_EPSILON));
}



        for (int i = 0; i < NUM_SINCOS_VALUES; ++i)
        {
            SetFunctionName("SinCos(a) test[%d]", i);
#ifdef HOST_TESTING
            Vector4 result = SinCos(sincos_values[i].input);
#else
            Vector4 result = SinCos<FloatType>(sincos_values[i].input);
#endif

            Validate(IsEqualWithEpsilon((float)result.X(), sincos_values[i].output1, FSINCOS_EPSILON));
            Validate(IsEqualWithEpsilon((float)result.Y(), sincos_values[i].output2, FSINCOS_EPSILON));
        }



        for (int i = 0; i < NUM_SINCOS_VALUES; ++i)
        {
            SetFunctionName("SinCosFast(a) test[%d]", i);
#ifdef HOST_TESTING
            Vector4 result = SinCosFast(sincos_values[i].input);
#else
            Vector4 result = SinCosFast<FloatType>((float_test_type) sincos_values[i].input);
#endif

            Validate(IsEqualWithEpsilon((float)result.X(), sincos_values[i].output1, FSINCOS_EPSILON));
            Validate(IsEqualWithEpsilon((float)result.Y(), sincos_values[i].output2, FSINCOS_EPSILON));
        }



        for (int i = 0; i < NUM_SINCOS_VALUES; ++i)
        {
            int i2 = NUM_SINCOS_VALUES - (i+1);
            SetFunctionName("SinCosFast2(a,b) test[%d]", i);
#ifdef HOST_TESTING
            Vector4 result = SinCosFast2(sincos_values[i].input,sincos_values[i2].input);
#else
            Vector4 result = SinCosFast2<FloatType>( (float_test_type)sincos_values[i].input, (float_test_type)sincos_values[i2].input);
#endif

            Validate(IsEqualWithEpsilon((float)result.X(), sincos_values[i].output1, FSINCOS_EPSILON));
            Validate(IsEqualWithEpsilon((float)result.Y(), sincos_values[i].output2, FSINCOS_EPSILON));
            Validate(IsEqualWithEpsilon((float)result.Z(), sincos_values[i2].output1, FSINCOS_EPSILON));
            Validate(IsEqualWithEpsilon((float)result.W(), sincos_values[i2].output2, FSINCOS_EPSILON));
        }



